package dev.zomboid.perf12;import java.util.*;
public class GraphChecks12{static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}public static class Graph{LinkedHashMap<Object,LinkedHashMap<Object,Integer>>g=new LinkedHashMap<>();void vertex(Object x){g.computeIfAbsent(x,k->new LinkedHashMap<>());}void edge(Object a,Object b,int w){vertex(a);vertex(b);g.get(a).put(b,w);}public int getVertexCount(){return g.size();}public Set<Object>vertices(){return g.keySet();}public Set<Object>targets(Object x){return g.get(x).keySet();}public OptionalInt get(Object a,Object b){Integer v=g.get(a).get(b);return v==null?OptionalInt.empty():OptionalInt.of(v);}}public static class Manager{Map<Integer,Graph>types=new TreeMap<>();}
 public static void main(String[]a)throws Exception{Random r=new Random(12);for(int trial=0;trial<100;trial++){Graph g=new Graph();int size=20+r.nextInt(120);for(int i=0;i<size;i++)g.vertex(i);for(int i=0;i<size;i++)for(int j=i+1;j<size;j++)if(r.nextDouble()<.05)g.edge(i,j,1+r.nextInt(10));List<Object>out=GraphOrder12.sort(g);ok(new HashSet<>(out).size()==size&&out.size()==size,"every render layer exactly once");Map<Object,Integer>index=new HashMap<>();for(int i=0;i<size;i++)index.put(out.get(i),i);for(Object x:g.vertices())for(Object y:g.targets(x))ok(index.get(x)<index.get(y),"DAG transparency constraints preserved");}Graph cycle=new Graph();cycle.edge("A","B",100);cycle.edge("B","C",100);cycle.edge("C","A",1);ok(GraphOrder12.sort(cycle).equals(List.of("A","B","C")),"cycle breaks weakest incoming dependency");Graph large=new Graph();for(int i=0;i<3000;i++)large.vertex(i);long start=System.nanoTime();ok(GraphOrder12.sort(large).size()==3000,"oversized graph uses bounded stable fallback");Graph dense=new Graph();for(int i=0;i<260;i++)for(int j=0;j<260;j++)if(i!=j)dense.edge(i,j,1);ok(GraphOrder12.sort(dense).size()==260,"edge budget preserves every layer");Manager m=new Manager();Graph first=new Graph(),second=new Graph();for(int i=0;i<10;i++){first.vertex("a"+i);second.vertex("b"+i);}m.types.put(0,first);m.types.put(1,second);List<?>order=(List<?>)GraphOrder12.order(m);ok(order.size()==20&&order.get(0).equals("a0")&&order.get(10).equals("b0"),"native transparency category order preserved");Manager small=new Manager();small.types.put(0,cycle);ok(GraphOrder12.order(small)==null,"tiny scenes keep native Iris sort");System.out.println("IRIS_WEIGHTED_DAG_CYCLE_BUDGET_CATEGORY_PRESERVATION_CHECKS="+checks+" fallback_ms="+(System.nanoTime()-start)/1e6);}}
